// Reads the static config (mounted read-only at /config) and the
// pipeline's persisted state (seen items + last run time, under /data).
// State won't exist on the very first run — default it instead of failing.
const fs = require('fs');

const config = JSON.parse(fs.readFileSync('/config/config.json', 'utf8'));

let state;
try {
  state = JSON.parse(fs.readFileSync('/data/state.json', 'utf8'));
} catch (e) {
  state = { seen_ids: [], last_run_at: null };
}

return [{ json: { config, state } }];

// Fan out config.sources into one item per RSS source, carrying config
// and state along so later nodes (reached via pairedItem lookups) can
// still read them without re-loading anything.
const { config, state } = items[0].json;

return config.sources.map((src) => ({
  json: {
    name: src.name,
    url: src.url,
    category: src.category,
    config,
    state
  }
}));

// Each feed entry has no built-in link back to the source it came from.
// RSS Feed Read fans 3 source items out into ~15 entries, and n8n's
// pairedItem tracking across that fan-out is ambiguous (`.item` throws
// "Multiple matches") — so match each entry to its source by comparing
// hostnames instead of relying on item-pairing at all.
const sources = $('Build Source List').all().map((i) => i.json);
const config = sources[0]?.config;
const state = sources[0]?.state;

function hostnameOf(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    return '';
  }
}

const sourceByHost = {};
for (const src of sources) {
  sourceByHost[hostnameOf(src.url)] = src;
}

return items.map((item) => {
  const entry = item.json;
  const host = hostnameOf(entry.link || entry.guid || '');
  const src = sourceByHost[host];

  return {
    json: {
      source_name: src ? src.name : 'unknown',
      category: src ? src.category : undefined,
      config,
      state,
      title: entry.title || '(untitled)',
      link: entry.link,
      guid: entry.guid || entry.link,
      pub_date: entry.isoDate || entry.pubDate,
      snippet: String(entry.contentSnippet || entry.content || entry.summary || '').slice(0, 500)
    }
  };
});

// Combines three jobs that all need the full cross-source item list at
// once: skip items already sent (by source+guid), skip items older than
// the last successful run (or the first-run lookback window), and cap how
// many items per source go on to the (paid) scoring step.
//
// A node with zero output items is skipped entirely by n8n, which would
// silently break the "always write a run log" requirement — so this node
// always returns exactly one item when there's nothing to score, tagged
// with `_empty`, carrying config/state forward so Finalize can still run.
const all = items.map((i) => i.json);
const cfg = all[0]?.config;
const state = all[0]?.state;

if (!all.length || !cfg) {
  return [{ json: { _empty: true, config: cfg, state, fetched_count: 0 } }];
}

const seen = new Set(state.seen_ids || []);
const cutoff = state.last_run_at
  ? new Date(state.last_run_at)
  : new Date(Date.now() - (cfg.run?.lookback_hours_on_first_run || 24) * 3600 * 1000);
const maxPerSource = cfg.run?.max_items_per_source || 20;

const perSourceCount = {};
const out = [];

for (const e of all) {
  const key = `${e.source_name}::${e.guid}`;
  if (seen.has(key)) continue;

  const pub = e.pub_date ? new Date(e.pub_date) : null;
  if (pub && pub <= cutoff) continue;

  perSourceCount[e.source_name] = (perSourceCount[e.source_name] || 0) + 1;
  if (perSourceCount[e.source_name] > maxPerSource) continue;

  out.push({
    json: {
      title: e.title,
      link: e.link,
      source_name: e.source_name,
      dedupe_key: key,
      snippet: e.snippet,
      config: cfg,
      state,
      fetched_count: all.length
    }
  });
}

if (!out.length) {
  return [{ json: { _empty: true, config: cfg, state, fetched_count: all.length } }];
}

return out;

// Scores every surviving candidate against the configured rubric using
// the Anthropic Messages API (model name comes from config.llm.model).
// If "Dedupe, Filter & Cap" found nothing new, this node is still called
// with exactly one `_empty` item — skip the API entirely and pass an
// all-zero result through, so Finalize always has something to log.
const first = items[0].json;

if (items.length === 1 && first._empty) {
  return [{
    json: {
      kept: [],
      errors: [],
      scored_count: 0,
      fetched_count: first.fetched_count || 0,
      token_usage: { input_tokens: 0, output_tokens: 0 },
      config: first.config,
      state: first.state
    }
  }];
}

const cfg = first.config;
const state = first.state;
const rubric = cfg.rubric;
const threshold = cfg.threshold;
const apiKey = $env.LLM_API_KEY;

const kept = [];
const errors = [];
let inTok = 0;
let outTok = 0;

for (const it of items) {
  const c = it.json;

  const promptText = [
    rubric.instructions,
    `Criteria:\n${JSON.stringify(rubric.criteria)}`,
    `Exclude:\n${JSON.stringify(rubric.exclude)}`,
    `Headline: ${c.title}`,
    `Snippet: ${c.snippet}`
  ].join('\n\n');

  const requestBody = {
    model: cfg.llm.model,
    max_tokens: 400,
    thinking: { type: 'disabled' },
    output_config: {
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            // Anthropic structured outputs don't support numerical
            // constraints like minimum/maximum (400: "not supported") —
            // the 0-10 range is stated here and in the rubric prompt
            // instead, and enforced in code below (clamp + validity check).
            score: { type: 'integer', description: 'Relevance score from 0 (irrelevant) to 10 (must-read).' },
            summary: { type: 'string', description: 'One-line summary of the item.' },
            why_it_matters: { type: 'string', description: 'One-line reason this matters to the reader.' }
          },
          required: ['score', 'summary', 'why_it_matters'],
          additionalProperties: false
        }
      }
    },
    messages: [{ role: 'user', content: promptText }]
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'content-type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01'
    },
    body: requestBody,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  if (response.statusCode < 200 || response.statusCode >= 300) {
    // Infra/auth-level failures (bad key, rate limit, outage) abort the
    // whole run so the error workflow fires — a single bad feed item
    // shouldn't silently eat the rest of the run, but a dead credential
    // should be loud, not logged as 20 quiet per-item errors.
    throw new Error(`Anthropic API error ${response.statusCode} for "${c.title}": ${JSON.stringify(response.body).slice(0, 300)}`);
  }

  const data = response.body;
  inTok += data.usage?.input_tokens || 0;
  outTok += data.usage?.output_tokens || 0;

  try {
    const text = data.content?.[0]?.text ?? '';
    const parsed = JSON.parse(text);

    // The schema can't enforce the 0-10 range (see note above), so a
    // missing or non-numeric score is treated as this item's error rather
    // than silently coerced into a number or defaulted to 0/kept.
    if (typeof parsed.score !== 'number' || Number.isNaN(parsed.score)) {
      errors.push(`Invalid score for "${c.title}": ${JSON.stringify(parsed.score)}`);
      continue;
    }

    const score = Math.min(10, Math.max(0, parsed.score));
    if (score >= threshold) {
      kept.push({
        title: c.title,
        link: c.link,
        source_name: c.source_name,
        score,
        summary: parsed.summary,
        why_it_matters: parsed.why_it_matters,
        dedupe_key: c.dedupe_key
      });
    }
  } catch (e) {
    errors.push(`Parse error for "${c.title}": ${e.message}`);
  }
}

return [{
  json: {
    kept,
    errors,
    scored_count: items.length,
    fetched_count: first.fetched_count,
    token_usage: { input_tokens: inTok, output_tokens: outTok },
    config: cfg,
    state
  }
}];

// Persists the new dedupe state + appends one line to the run log, then
// builds the Telegram message text. Runs exactly once per execution no
// matter which branch fed it, since it only ever receives the single
// summary item "Score Candidates (Claude)" always produces.
const fs = require('fs');

const input = items[0].json;
const config = input.config;
const state = input.state;
const kept = input.kept || [];
const errors = input.errors || [];
const fetchedCount = input.fetched_count || 0;
const scoredCount = input.scored_count || 0;
const tokenUsage = input.token_usage || { input_tokens: 0, output_tokens: 0 };

const newSeen = new Set(state.seen_ids || []);
for (const k of kept) newSeen.add(k.dedupe_key);
// Trim so the dedupe file doesn't grow forever.
const trimmedSeen = Array.from(newSeen).slice(-2000);

const newState = { seen_ids: trimmedSeen, last_run_at: new Date().toISOString() };
fs.mkdirSync('/data', { recursive: true });
fs.writeFileSync('/data/state.json', JSON.stringify(newState, null, 2));

const costPerMTokIn = config.llm.cost_per_mtok_input ?? 0;
const costPerMTokOut = config.llm.cost_per_mtok_output ?? 0;
const cost =
  (tokenUsage.input_tokens / 1e6) * costPerMTokIn + (tokenUsage.output_tokens / 1e6) * costPerMTokOut;

const logEntry = {
  timestamp: new Date().toISOString(),
  fetched: fetchedCount,
  scored: scoredCount,
  kept: kept.length,
  input_tokens: tokenUsage.input_tokens,
  output_tokens: tokenUsage.output_tokens,
  estimated_cost_usd: Number(cost.toFixed(4)),
  errors
};
fs.appendFileSync('/data/run-log.ndjson', JSON.stringify(logEntry) + '\n');

const sorted = [...kept].sort((a, b) => b.score - a.score);
const lines = sorted.map(
  (k, i) =>
    `${i + 1}. ${k.title} (${k.source_name}, score ${k.score}/10)\n${k.summary}\nWhy it matters: ${k.why_it_matters}\n${k.link}`
);

let messageText = kept.length
  ? `Music News Digest — ${kept.length} item(s)\n\n${lines.join('\n\n')}`
  : '';

// Telegram's hard message-length cap is 4096 characters.
if (messageText.length > 4000) {
  messageText = `${messageText.slice(0, 3980)}\n\n…(truncated)`;
}

return [{
  json: {
    ...logEntry,
    items: kept,
    has_items: kept.length > 0,
    message_text: messageText,
    chat_id: config.telegram.chat_id
  }
}];

// Nothing to send on a run that kept zero items — quietly do nothing
// rather than call the Telegram API with an empty message.
const input = items[0].json;
if (!input.has_items) {
  return [];
}

const token = $env.TELEGRAM_BOT_TOKEN;
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  headers: { 'content-type': 'application/json' },
  body: { chat_id: input.chat_id, text: input.message_text },
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});

if (response.statusCode < 200 || response.statusCode >= 300) {
  throw new Error(`Telegram API error ${response.statusCode}: ${JSON.stringify(response.body).slice(0, 300)}`);
}

const data = response.body;
return [{ json: { telegram_ok: data.ok === true } }];
